import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

public class Main {
    static int getWithRetries(HttpClient client, URI endpoint) throws Exception {
        for (int attempt = 1; attempt <= 3; attempt++) {
            HttpRequest request = HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(4)).GET().build();
            HttpResponse<Void> response = client.send(request, HttpResponse.BodyHandlers.discarding());
            int status = response.statusCode();
            if (status != 429 && status < 500) return status;
            if (attempt < 3) Thread.sleep(200L * attempt);
        }
        throw new IllegalStateException("Retry limit reached");
    }
    public static void main(String[] args) throws Exception {
        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
        System.out.println("HTTP status: " + getWithRetries(client, URI.create("https://example.com/")));
    }
}
